mapper.sql:
WHERE over_time_requests.is_active = 1
AND over_time_requests.employee_id = #{filter.employeeId}

    AND ( employees.name LIKE CONCAT("%", #{filter.searchText}, "%") OR employees.name_kh LIKE CONCAT("%", #{filter.searchText}, "%") )


    AND DATE(over_time_requests.date_time_from) >= #{filter.dateFrom} AND DATE(over_time_requests.date_time_to) <= #{filter.dateTo}

AND over_time_requests.status = #{filter.status}

mapper.select:
SELECT



ORDER BY


        ${filter.orderBy}


        over_time_requests.id DESC


LIMIT #{filter.page}, #{filter.rowsPerPage}

mapper.update:
UPDATE over_time_requests
SET status      = #{otRequest.status},
    status_date = NOW(),
    status_by   = #{otRequest.createdBy}
WHERE id = #{otRequest.id}

